  mt([("board game", "настільна гра"), ("card game", "карткова гра"), ("puzzle", "головоломка"), ("win", "вигравати"), ("lose", "програвати")], "Слова про ігри."),
  liu("We play a board game on Fridays.", "Прослухайте. Коли вони грають?", ["По п'ятницях", "По суботах", "По неділях"], "Fridays."),
  liu("I often win at chess.", "Прослухайте. Що каже людина?", ["Вона часто виграє в шахи", "Вона часто програє", "Вона не грає"], "Wins."),
  liu("My brother always loses.", "Прослухайте. Що робить брат?", ["Завжди програє", "Завжди виграє", "Не грає"], "Loses."),
  fb("We play a board ___ on Fridays.", ["game", "puzzle", "win"], "Board game."),
  fb("I often ___ at chess.", ["win", "wins", "winning"], "I win."),
  fb("My brother always ___.", ["loses", "lose", "losing"], "He loses."),
