  fb("We go for a ___.", ["picnic", "barbecue is", "garden"], "Picnic."),
  fb("I like being ___.", ["outdoors", "garden", "picnic"], "Outdoors."),
  mc("Як сказати «Ми влаштовуємо барбекю»?", ["We have a barbecue.", "We make a barbecue is.", "We are barbecue."], "Have a barbecue."),
  bs("У вільний час я читаю.", ["In", "my", "spare", "time", "I", "read"], ["on", "reads"], "In my spare time I read."),
